function generateConsumerQR() {
  if (typeof QRCode === 'undefined') {
    alert('QR Code 功能載入失敗，請確認網路連線後重新整理頁面。');
    return;
  }
  const baseUrl = window.location.origin + window.location.pathname;
  const uid = _fbAuth && _fbAuth.currentUser ? _fbAuth.currentUser.uid : '';
  const consumerUrl = baseUrl + '?view=consumer' + (uid ? '&uid=' + uid : '');
  window._consumerQrUrl = consumerUrl;

  document.getElementById('consumerLink').textContent = consumerUrl;
  document.getElementById('qrFarmLabel').textContent = `${farmProfile.farmer} · ${farmProfile.location}`;

  const container = document.getElementById('qrCodeCanvas');
  container.innerHTML = '';

  new QRCode(container, {
    text: consumerUrl,
    width: 190,
    height: 190,
    colorDark: '#111111',
    colorLight: '#ffffff',
    correctLevel: QRCode.CorrectLevel.M
  });

  document.getElementById('qrCodeDisplay').style.display = 'block';
}

function copyConsumerUrl() {
  const url = window._consumerQrUrl || '';
  if (!url) { alert('請先按「生成 QR Code」'); return; }
  navigator.clipboard.writeText(url)
    .then(() => showTicketToast('✓ 消費者連結已複製'))
    .catch(() => alert('請手動複製：' + url));
}

function downloadQrCode() {
  const container = document.getElementById('qrCodeCanvas');
  const canvas = container ? container.querySelector('canvas') : null;
  if (!canvas) { alert('請先按「生成 QR Code」'); return; }
  const a = document.createElement('a');
  a.href = canvas.toDataURL('image/png');
  a.download = `農場QR_${farmProfile.farmer || 'qrcode'}.png`;
  a.click();
}

function spawnSparkle(cx, cy) {
  const glyphs = ['✨','⭐','🌟','💫','🎉','🎊','⚡','🌈'];
  const el = document.createElement('div');
  el.className = 'gacha-spark';
  el.textContent = glyphs[Math.floor(Math.random() * glyphs.length)];
  el.style.left = (cx + (Math.random()-0.5)*130) + 'px';
  el.style.top  = (cy + (Math.random()-0.5)*70) + 'px';
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 1200);
}

function screenFlash() {
  const el = document.createElement('div');
  el.className = 'gacha-flash';
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 600);
}

function launchConfetti() {
  const card = document.querySelector('.gacha-modal-card');
  card.querySelectorAll('.confetti-dot').forEach(d => d.remove());
  const colors = ['#ff6b6b','#ffd93d','#6bcb77','#4d96ff','#ff9ff3','#ffa502','#ff6348','#7bed9f'];
  for (let i = 0; i < 32; i++) {
    const dot = document.createElement('div');
    dot.className = 'confetti-dot';
    const w = 5 + Math.random()*8;
    dot.style.cssText = `width:${w}px;height:${w}px;background:${colors[Math.floor(Math.random()*colors.length)]};left:${Math.random()*100}%;top:0;--dur:${1.2+Math.random()*1.1}s;--delay:${Math.random()*0.5}s`;
    card.appendChild(dot);
    setTimeout(() => dot.remove(), 3000);
  }
}

function drawLotteryCharacter() {
  if (characterPool.length === 0) {
    document.getElementById('lotteryResult').innerText = "目前尚未有角色可抽。";
    return;
  }
  if (isGachaSpinning) return;
  if (_tickets <= 0) {
    document.getElementById('lotteryResult').innerText = '🎟 沒有抽獎券了！完成今日全部任務或連續打卡可獲得。';
    return;
  }

  _tickets--;
  _saveTickets();

  isGachaSpinning = true;
  const button = document.getElementById('gachaButton');
  const result = document.getElementById('lotteryResult');
  const svg = document.querySelector('.gacha-svg-machine');
  button.disabled = true;
  button.innerText = '轉動中...';
  result.innerText = '扭蛋機正在轉動，請稍後...';
  svg.classList.add('spinning');

  document.getElementById('resultCircle').setAttribute('opacity', '0');
  document.getElementById('resultImg').setAttribute('opacity', '0');
  document.getElementById('resultQuestion').setAttribute('opacity', '0');

  const balls = [
    { el: document.getElementById('ball1'), shine: document.getElementById('ball1shine'), bx: 88, by: 78 },
    { el: document.getElementById('ball2'), shine: document.getElementById('ball2shine'), bx: 152, by: 68 },
    { el: document.getElementById('ball3'), shine: document.getElementById('ball3shine'), bx: 120, by: 100 },
  ];
  balls.forEach(b => { b.el.setAttribute('opacity', '0.92'); b.shine.setAttribute('opacity', '1'); });

  const svgRect = svg.getBoundingClientRect();
  const sparkInterval = setInterval(() => {
    spawnSparkle(svgRect.left + svgRect.width * 0.5, svgRect.top + svgRect.height * 0.3);
  }, 280);

  let t = 0;
  const spinInterval = setInterval(() => {
    t += 0.26;
    balls.forEach((b, i) => {
      const dx = Math.sin(t + i * 2.1) * 30;
      const dy = Math.cos(t * 1.4 + i * 1.6) * 22;
      b.el.setAttribute('cx', b.bx + dx);
      b.el.setAttribute('cy', b.by + dy);
      b.shine.setAttribute('cx', b.bx + dx - 8);
      b.shine.setAttribute('cy', b.by + dy - 8);
    });
  }, 30);

  setTimeout(() => {
    clearInterval(spinInterval);
    clearInterval(sparkInterval);
    svg.classList.remove('spinning');
    balls.forEach(b => { b.el.setAttribute('opacity', '0'); b.shine.setAttribute('opacity', '0'); });

    const randomCharacter = characterPool[Math.floor(Math.random() * characterPool.length)];
    window._lastGachaChar = randomCharacter;

    result.innerText = `恭喜抽中：${randomCharacter.name}！`;
    button.disabled = false;
    button.innerText = _tickets > 0 ? `🎟 再轉一次 (剩 ${_tickets})` : '🎟 無抽獎券';
    isGachaSpinning = false;

    screenFlash();
    setTimeout(() => {
      showGachaModal(randomCharacter);
      balls.forEach(b => { b.el.setAttribute('opacity', '0.92'); b.shine.setAttribute('opacity', '1'); });
      document.getElementById('resultCircle').setAttribute('opacity', '0');
      document.getElementById('resultImg').setAttribute('opacity', '0');
      document.getElementById('resultQuestion').setAttribute('opacity', '1');
    }, 350);
  }, 1800);
}

function showGachaModal(char) {
  const series = seriesMap[char.name] || '其他';
  const rarity = (typeof SERIES_RARITY !== 'undefined' && SERIES_RARITY[series]) ? SERIES_RARITY[series] : {stars:3,label:'R',color:'#60a5fa'};
  const overlay = document.getElementById('gachaModal');
  const card = overlay.querySelector('.gacha-modal-card');

  document.getElementById('gachaModalImg').src = char.img;
  document.getElementById('gachaModalImg').alt = char.name;
  document.getElementById('gachaModalName').innerText = char.name;

  // Set rarity
  const rarityEl = document.getElementById('gachaModalRarity');
  if (rarityEl) { rarityEl.innerText = rarity.label; rarityEl.style.color = rarity.color; }
  const starsEl = document.getElementById('gachaModalStars');
  if (starsEl) {
    starsEl.innerHTML = Array.from({length:5},(_,i)=>
      `<svg width="18" height="18" viewBox="0 0 24 24" fill="${i<rarity.stars?rarity.color:'rgba(255,255,255,0.15)'}"><polygon points="12,2 15.09,8.26 22,9.27 17,14.14 18.18,21.02 12,17.77 5.82,21.02 7,14.14 2,9.27 8.91,8.26"/></svg>`
    ).join('');
  }
  card.style.setProperty('--rarity-glow', `linear-gradient(160deg,${rarity.color}18,transparent 60%)`);
  card.style.setProperty('--rarity-shadow', rarity.color+'66');
  card.style.boxShadow = `0 20px 60px rgba(0,0,0,0.6), 0 0 40px ${rarity.color}44`;

  card.style.animation = 'popIn 0.45s cubic-bezier(0.175,0.885,0.32,1.275)';
  overlay.classList.add('active');
  setTimeout(() => {
    card.style.animation = '';
    launchConfetti();
  }, 460);
}

function closeGachaModal() {
  const overlay = document.getElementById('gachaModal');
  const card = overlay.querySelector('.gacha-modal-card');
  overlay.classList.remove('active');
  card.style.animation = '';
}

