let timelineSelectedYear = null;
let timelineSelectedMonth = null;
let timelineSelectedDay = null;
let timelineAvailableDates = new Set();

function normalizeTimelineDate(value) {
  const match = String(value || '').match(/(\d{4})[/-](\d{1,2})[/-](\d{1,2})/);
  if (!match) return '';
  return `${match[1]}/${String(Number(match[2])).padStart(2, '0')}/${String(Number(match[3])).padStart(2, '0')}`;
}

function timelineLogFullDate(log, fallbackYear = new Date().getFullYear()) {
  const fullDate = normalizeTimelineDate(log && log.fullDate);
  if (fullDate) return fullDate;
  const dateText = String((log && log.date) || '');
  const fullFromDate = normalizeTimelineDate(dateText);
  if (fullFromDate) return fullFromDate;
  const md = dateText.match(/(\d{1,2})[/-](\d{1,2})/);
  return md ? `${fallbackYear}/${String(Number(md[1])).padStart(2, '0')}/${String(Number(md[2])).padStart(2, '0')}` : '';
}

function timelineMinutes(value) {
  const match = String(value || '').match(/(\d{1,2}):(\d{2})/);
  return match ? Number(match[1]) * 60 + Number(match[2]) : null;
}

function closeTimelineDatePicker() {
  const picker = document.getElementById('timelineDatePicker');
  const selector = document.getElementById('timelineMonthLabel');
  if (picker) {
    picker.classList.remove('open');
    picker.setAttribute('aria-hidden', 'true');
  }
  if (selector) selector.setAttribute('aria-expanded', 'false');
}

function toggleTimelineDatePicker(event) {
  if (event) event.stopPropagation();
  const picker = document.getElementById('timelineDatePicker');
  const selector = document.getElementById('timelineMonthLabel');
  if (!picker || !selector) return;
  const opening = !picker.classList.contains('open');
  picker.classList.toggle('open', opening);
  picker.setAttribute('aria-hidden', String(!opening));
  selector.setAttribute('aria-expanded', String(opening));
  if (opening) renderTimelineDatePicker();
}

function changeTimelineYear(value) {
  timelineSelectedYear = Number(value);
  timelineSelectedDay = null;
  renderDailyTimeline();
}

function changeTimelineMonth(value) {
  timelineSelectedMonth = Number(value);
  timelineSelectedDay = null;
  renderDailyTimeline();
}

function shiftTimelineMonth(step) {
  let year = Number(timelineSelectedYear);
  let month = Number(timelineSelectedMonth) + step;
  if (month < 1) { month = 12; year -= 1; }
  if (month > 12) { month = 1; year += 1; }
  timelineSelectedYear = year;
  timelineSelectedMonth = month;
  timelineSelectedDay = null;
  renderDailyTimeline();
}

function selectTimelineDay(day) {
  timelineSelectedDay = Number(day);
  renderDailyTimeline();
  closeTimelineDatePicker();
}

function showTimelineWholeMonth() {
  timelineSelectedDay = null;
  renderDailyTimeline();
  closeTimelineDatePicker();
}

function renderTimelineDatePicker() {
  const yearSelect = document.getElementById('timelineYearSelect');
  const monthSelect = document.getElementById('timelineMonthSelect');
  const daysEl = document.getElementById('timelineCalendarDays');
  if (!yearSelect || !monthSelect || !daysEl || !timelineSelectedYear || !timelineSelectedMonth) return;

  const availableYears = [...timelineAvailableDates].map(date => Number(date.slice(0, 4))).filter(Boolean);
  const currentYear = new Date().getFullYear();
  const minYear = Math.min(currentYear - 3, timelineSelectedYear, ...(availableYears.length ? availableYears : [timelineSelectedYear]));
  const maxYear = Math.max(currentYear + 3, timelineSelectedYear, ...(availableYears.length ? availableYears : [timelineSelectedYear]));
  yearSelect.innerHTML = Array.from({ length: maxYear - minYear + 1 }, (_, index) => {
    const year = minYear + index;
    return `<option value="${year}"${year === timelineSelectedYear ? ' selected' : ''}>${year}年</option>`;
  }).join('');
  monthSelect.innerHTML = Array.from({ length: 12 }, (_, index) => {
    const month = index + 1;
    return `<option value="${month}"${month === timelineSelectedMonth ? ' selected' : ''}>${month}月</option>`;
  }).join('');

  const firstWeekday = new Date(timelineSelectedYear, timelineSelectedMonth - 1, 1).getDay();
  const daysInMonth = new Date(timelineSelectedYear, timelineSelectedMonth, 0).getDate();
  const cells = Array.from({ length: firstWeekday }, () => '<button class="cs-picker-day" type="button" disabled aria-hidden="true"></button>');
  for (let day = 1; day <= daysInMonth; day += 1) {
    const dateKey = `${timelineSelectedYear}/${String(timelineSelectedMonth).padStart(2, '0')}/${String(day).padStart(2, '0')}`;
    const hasRecords = timelineAvailableDates.has(dateKey);
    const selected = timelineSelectedDay === day;
    cells.push(`<button class="cs-picker-day${hasRecords ? ' has-records' : ''}${selected ? ' selected' : ''}" type="button" role="gridcell" aria-label="${timelineSelectedYear}年${timelineSelectedMonth}月${day}日${hasRecords ? '，有紀錄' : ''}" onclick="selectTimelineDay(${day})">${day}</button>`);
  }
  daysEl.innerHTML = cells.join('');
}

document.addEventListener('click', event => {
  const picker = document.getElementById('timelineDatePicker');
  const selector = document.getElementById('timelineMonthLabel');
  if (picker && picker.classList.contains('open') && !picker.contains(event.target) && event.target !== selector) {
    closeTimelineDatePicker();
  }
});

function renderDailyTimeline() {
  const el = document.getElementById('dailyTimeline');
  if (!el) return;
  const dailyPhotos = JSON.parse(localStorage.getItem('puli_daily_photos') || '[]');
  const previewOnly = logs.length === 0 && dailyPhotos.length === 0;
  // These records exist only for rendering the empty consumer preview.
  // They are never written to localStorage, Firebase, or the real logs array.
  const previewLogs = [
    {
      fullDate: '2026/07/29',
      date: '07/29 09:20',
      type: '玉米',
      name: '晨間巡田',
      temp: 26.4,
      hum: 72,
      ph: 6.5,
      note: '葉片舒展、土壤濕潤，完成晨間灌溉與生長觀察。',
      previewOnly: true
    },
    {
      fullDate: '2026/07/27',
      date: '07/27 15:40',
      type: '苦瓜',
      name: '藤蔓整理',
      temp: 27.1,
      hum: 68,
      ph: 6.3,
      note: '整理攀藤方向並移除老葉，日照與通風狀態良好。',
      previewOnly: true
    },
    {
      fullDate: '2026/07/25',
      date: '07/25 07:35',
      type: '青江菜',
      name: '採收前檢查',
      temp: 24.8,
      hum: 76,
      ph: 6.6,
      note: '株型飽滿、葉色均勻，已完成採收前品質確認。',
      previewOnly: true
    }
  ];
  const timelineLogs = previewOnly ? previewLogs : logs;
  const fallbackYear = new Date().getFullYear();
  const photosByDate = {};
  dailyPhotos.forEach(photo => {
    const date = normalizeTimelineDate(photo.date);
    if (!date) return;
    if (!photosByDate[date]) photosByDate[date] = [];
    photosByDate[date].push(photo);
  });

  const allDates = new Set([
    ...timelineLogs.map(log => timelineLogFullDate(log, fallbackYear)),
    ...Object.keys(photosByDate)
  ].filter(Boolean));
  const allSortedDates = [...allDates].sort((a, b) => b.localeCompare(a));
  timelineAvailableDates = new Set(allSortedDates);

  if (!timelineSelectedYear || !timelineSelectedMonth) {
    const initialDate = allSortedDates[0] || normalizeTimelineDate(new Date().toLocaleDateString('zh-TW'));
    const [year, month] = initialDate.split('/').map(Number);
    timelineSelectedYear = year;
    timelineSelectedMonth = month;
  }

  const selectedMonthKey = `${timelineSelectedYear}/${String(timelineSelectedMonth).padStart(2, '0')}`;
  const selectedDayKey = timelineSelectedDay
    ? `${selectedMonthKey}/${String(timelineSelectedDay).padStart(2, '0')}`
    : '';
  const sorted = allSortedDates.filter(date => selectedDayKey ? date === selectedDayKey : date.startsWith(`${selectedMonthKey}/`));
  const palette = ['#80e5a0','#64b5f6','#ffb74d','#f48fb1','#b39ddb'];
  const monthLabel = document.getElementById('timelineMonthLabel');
  if (monthLabel) monthLabel.textContent = `${timelineSelectedYear}年${timelineSelectedMonth}月`;

  if (sorted.length === 0) {
    el.innerHTML = `<div class="tl-empty">
      <div class="tl-empty-title">${timelineSelectedDay ? `${timelineSelectedMonth}月${timelineSelectedDay}日` : `${timelineSelectedYear}年${timelineSelectedMonth}月`}尚無農事記錄</div>
      <div class="tl-empty-text">可選擇其他日期，或點選「顯示整月」查看本月全部紀錄。</div>
    </div>`;
    renderTimelineDatePicker();
    return;
  }

  el.innerHTML = sorted.map((date, idx) => {
    const dayLogs = timelineLogs.filter(log => timelineLogFullDate(log, fallbackYear) === date);
    const unmatchedPhotos = [...(photosByDate[date] || [])];
    const [yyyy, mm, dd] = date.split('/');
    const weekDay = ['日','一','二','三','四','五','六'][new Date(Number(yyyy), Number(mm) - 1, Number(dd)).getDay()];
    const color = palette[idx % palette.length];
    const items = [];

    dayLogs.forEach(log => {
      const timeStr = log.date ? log.date.split(' ').slice(1).join(' ') : '';
      let recordImage = log.img || log.image || log.photo || '';
      if (!recordImage && unmatchedPhotos.length) {
        const logMinute = timelineMinutes(timeStr);
        let photoIndex = 0;
        if (logMinute !== null) {
          let closestDifference = Infinity;
          unmatchedPhotos.forEach((photo, index) => {
            const photoMinute = timelineMinutes(photo.time);
            const difference = photoMinute === null ? Infinity : Math.abs(photoMinute - logMinute);
            if (difference < closestDifference) {
              closestDifference = difference;
              photoIndex = index;
            }
          });
        }
        recordImage = unmatchedPhotos.splice(photoIndex, 1)[0]?.img || '';
      }
      if (!recordImage && log.previewOnly) recordImage = consumerWikiImages[log.type] || '';

      items.push(`<div class="tl-item">
        <div class="tl-dot-circle" style="background:${color};"></div>
        <div class="tl-card${recordImage ? ' has-thumb' : ''}">
          <div class="tl-card-body">
            <div class="tl-card-time-row">
              ${timeStr ? `<div class="tl-card-time">${timeStr}</div>` : ''}
              ${log.previewOnly ? '<span class="tl-preview-chip">版面預覽</span>' : ''}
            </div>
            <div class="tl-card-crop">${log.type || '農場作物'}${log.name && log.name !== '今日批次' ? ' · '+log.name : ''}</div>
            <div class="tl-card-tags">
              ${log.temp ? `<span class="tl-card-tag">溫 ${log.temp}°C</span>` : ''}
              ${log.hum  ? `<span class="tl-card-tag">濕 ${log.hum}%</span>` : ''}
              ${log.ph && log.ph !== '--' ? `<span class="tl-card-tag">pH ${log.ph}</span>` : ''}
            </div>
            ${log.note ? `<div class="tl-card-note">${log.note}</div>` : ''}
          </div>
          ${recordImage ? `<img class="tl-card-thumb" src="${recordImage}" alt="${log.type || '農事紀錄'}照片">` : ''}
        </div>
      </div>`);
    });

    unmatchedPhotos.forEach(photo => {
      items.push(`<div class="tl-item">
        <div class="tl-dot-circle" style="background:${color};"></div>
        <div class="tl-card has-thumb">
          <div class="tl-card-body">
            <div class="tl-card-time">${photo.time || ''}</div>
            <div class="tl-card-crop">植物照片紀錄</div>
            <div class="tl-card-note">當日生長影像紀錄</div>
          </div>
          <img class="tl-card-thumb" src="${photo.img}" alt="植物照片">
        </div>
      </div>`);
    });

    return `<div class="tl-section" id="timeline-date-${yyyy}-${mm}-${dd}">
      <div class="tl-date-column">
        <div class="tl-date-box" style="border-color:${color}55;background:${color}18;">
          <div class="tl-date-day" style="color:${color};">${dd}</div>
          <div class="tl-date-sub">${mm}月（${weekDay}）</div>
          <div class="tl-year">${yyyy}</div>
        </div>
        <div class="tl-date-track" style="background:linear-gradient(180deg,${color},${color}12);"></div>
      </div>
      <div class="tl-day-content">${items.join('')}</div>
    </div>`;
  }).join('');
  renderTimelineDatePicker();
}

let _cameraStream = null;

function startCamera() {
  const viewport = document.getElementById('cameraViewport');
  const video = document.getElementById('cameraStream');
  const preview = document.getElementById('farmerPhotoPreview');
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    document.getElementById('farmerPhotoInput').click(); return;
  }
  navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' }, audio: false })
    .then(stream => {
      _cameraStream = stream;
      video.srcObject = stream;
      viewport.style.display = 'block';
      preview.style.display = 'none';
      document.getElementById('photoButtons').style.display = 'none';
    })
    .catch(() => { document.getElementById('farmerPhotoInput').click(); });
}

function stopCamera() {
  if (_cameraStream) { _cameraStream.getTracks().forEach(t => t.stop()); _cameraStream = null; }
  document.getElementById('cameraViewport').style.display = 'none';
  document.getElementById('farmerPhotoPreview').style.display = 'flex';
  document.getElementById('photoButtons').style.display = 'flex';
}

function capturePhoto() {
  const video = document.getElementById('cameraStream');
  const canvas = document.getElementById('cameraCanvas');
  canvas.width = video.videoWidth;
  canvas.height = video.videoHeight;
  canvas.getContext('2d').drawImage(video, 0, 0);
  const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
  stopCamera();
  applyFarmerPhoto(dataUrl);
}

function applyFarmerPhoto(dataUrl) {
  // Compress to max 800px / 75% before storing to avoid localStorage quota issues
  const img = new Image();
  img.onload = function() {
    const MAX = 800;
    let w = img.width, h = img.height;
    if (w > MAX) { h = Math.round(h * MAX / w); w = MAX; }
    if (h > MAX) { w = Math.round(w * MAX / h); h = MAX; }
    const cv = document.createElement('canvas');
    cv.width = w; cv.height = h;
    cv.getContext('2d').drawImage(img, 0, 0, w, h);
    const compressed = cv.toDataURL('image/jpeg', 0.75);
    _storePhoto(compressed);
  };
  img.onerror = function() { _storePhoto(dataUrl); }; // fallback: store as-is
  img.src = dataUrl;
}

function _storePhoto(dataUrl) {
  const now = new Date();
  const dateKey = now.toLocaleDateString('zh-TW', {year:'numeric',month:'2-digit',day:'2-digit'});
  const timeKey = now.toLocaleTimeString('zh-TW', {hour:'2-digit',minute:'2-digit',hour12:false});
  let dailyPhotos = JSON.parse(localStorage.getItem('puli_daily_photos') || '[]');
  dailyPhotos.unshift({ date: dateKey, time: timeKey, img: dataUrl });
  let saved = false;
  while (dailyPhotos.length > 0 && !saved) {
    try {
      localStorage.setItem('puli_daily_photos', JSON.stringify(dailyPhotos));
      localStorage.setItem('puli_plant_photo', dataUrl);
      saved = true;
    } catch(e) {
      // Storage full — drop oldest photo and retry
      dailyPhotos.pop();
    }
  }
  if (!saved) { alert('儲存空間已滿，照片無法儲存。請先刪除部分舊照片。'); return; }
  renderFarmerPhotoGrid();
  renderDailyTimeline();
  // 今天第一次上傳照片才給 EXP
  const _todayForExp = _getTodayStr();
  const _existingPhotos = JSON.parse(localStorage.getItem('puli_daily_photos') || '[]');
  const _todayPhotoCount = _existingPhotos.filter(p => p.date === _todayForExp).length;
  if (_todayPhotoCount <= 1) addExp(EXP_REWARDS.dailyPhoto, '上傳今日植物照片');
  renderTaskView();
  renderHomeWidgets();
  _tryAwardDailyTaskTicket();
  _tryAwardStreakTicket();
}

function deleteFarmerPhoto(index) {
  if (!confirm('確定刪除這張照片？')) return;
  let dailyPhotos = JSON.parse(localStorage.getItem('puli_daily_photos') || '[]');
  dailyPhotos.splice(index, 1);
  localStorage.setItem('puli_daily_photos', JSON.stringify(dailyPhotos));
  if (dailyPhotos.length > 0) localStorage.setItem('puli_plant_photo', dailyPhotos[0].img);
  else localStorage.removeItem('puli_plant_photo');
  renderFarmerPhotoGrid();
  renderDailyTimeline();
}

function renderFarmerPhotoGrid() {
  const grid = document.getElementById('farmerPhotoGrid');
  if (!grid) return;
  const dailyPhotos = JSON.parse(localStorage.getItem('puli_daily_photos') || '[]');
  if (dailyPhotos.length === 0) {
    grid.innerHTML = '<div class="farmer-photo-empty">尚無照片，請使用上方按鈕拍攝或上傳</div>';
    return;
  }

  // Group by date, preserve original index for delete
  const byDate = {};
  dailyPhotos.forEach((p, i) => {
    const d = p.date || '未知日期';
    if (!byDate[d]) byDate[d] = [];
    byDate[d].push({ ...p, _idx: i });
  });
  const dates = Object.keys(byDate).sort((a, b) => b.localeCompare(a));

  const today = new Date().toLocaleDateString('zh-TW', {year:'numeric',month:'2-digit',day:'2-digit'});

  let html = '';
  dates.forEach(date => {
    const label = date === today ? `今天　${date}` : date;
    html += `<div style="grid-column:1/-1;font-size:12px;font-weight:700;color:rgba(255,255,255,0.5);padding:10px 2px 4px;letter-spacing:0.5px;border-top:1px solid rgba(255,255,255,0.08);margin-top:2px;">${label}</div>`;
    html += byDate[date].map(p => `
      <div class="farmer-photo-item">
        <img src="${p.img}" alt="植物照片">
        <div class="farmer-photo-badge">${p.time || ''}</div>
        <button class="farmer-photo-del" onclick="deleteFarmerPhoto(${p._idx})" title="刪除">✕</button>
      </div>`).join('');
  });

  grid.innerHTML = html;
}

