function saveQuickLog() {
  const crop = document.getElementById('quickCrop').value.trim() || '農場作物';
  const batch = document.getElementById('quickBatch') ? document.getElementById('quickBatch').value.trim() : '';
  const temp = parseFloat(document.getElementById('quickTemp') ? document.getElementById('quickTemp').value : '') || 0;
  const hum = parseFloat(document.getElementById('quickHum') ? document.getElementById('quickHum').value : '') || 0;
  const ph = document.getElementById('quickPH') ? (document.getElementById('quickPH').value.trim() || '--') : '--';
  const note = document.getElementById('quickNote').value.trim() || '例行性巡視，生長狀況良好。';
  const now = new Date();
  const fullDate = now.toLocaleDateString('zh-TW', {year:'numeric',month:'2-digit',day:'2-digit'});
  const timeStr = now.toLocaleString('zh-TW', {month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
  const newLog = {
    date: timeStr,
    fullDate: fullDate,
    type: crop, name: batch || '今日批次', temp, hum, ph, note
  };
  logs.unshift(newLog);
  localStorage.setItem('puli_dynamic_resume', JSON.stringify(logs));
  ['quickCrop','quickBatch','quickTemp','quickHum','quickPH','quickNote'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  alert('紀錄已儲存！消費者頁面已更新。');
  // 今天第一筆日誌才給 EXP
  const _todayMD = _getTodayStr().slice(5);
  const _todayLogCount = logs.filter(l => l.fullDate === _getTodayStr() || (l.date && l.date.startsWith(_todayMD))).length;
  if (_todayLogCount <= 1) addExp(EXP_REWARDS.dailyLog, '記錄今日觀測日誌');
  renderTaskView();
  renderHomeWidgets();
  closeQuickLogModal();
  _tryAwardDailyTaskTicket();
  _tryAwardStreakTicket();
}

function switchView(viewId) {
  const targetView = document.getElementById(viewId);
  if (!targetView) { console.error('找不到 viewId：', viewId); return; }
  const vp = document.querySelector('meta[name="viewport"]');
  if (vp) vp.setAttribute('content', 'width=device-width, initial-scale=1, viewport-fit=cover');
  document.querySelectorAll('.view-screen').forEach(v => v.classList.remove('active'));
  targetView.classList.add('active');

  // Sync bottom tab bar
  const tabMap = { viewFarmer:'tab-farmer', viewConsumer:'tab-consumer', viewGallery:'tab-gallery', viewTask:'tab-task', viewMe:'tab-me' };
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
  const activeTab = document.getElementById(tabMap[viewId]);
  if (activeTab) activeTab.classList.add('active');

  if (viewId === 'viewFarmer')  { renderFarmerPhotoGrid(); renderHomeWidgets(); }
  if (viewId === 'viewMe') { renderMePage(); }
  if (viewId === 'viewConsumer') { initChart(); renderDailyTimeline(); generateRandomWiki(); setTimeout(loadConsumerPublicProfile, 400); }
  if (viewId === 'viewTask') { renderTaskView(); }
}

