// ── Firebase Auth ─────────────────────────────────────────
let _loginMode = 'login'; // 'login' | 'register' | 'forgot'

function initAuth() {
  // Consumer view is always public
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('view') === 'consumer' || window.location.hash === '#consumer') {
    startApp(); return;
  }
  // 偵測是否以本機檔案開啟（file:// 或手機下載後直接開啟的 content://）
  // 這種情況下 Firebase 的網路請求會被瀏覽器擋下，登入會卡在「處理中」不動
  if (location.protocol === 'file:' || location.protocol === 'content:') {
    const err = document.getElementById('loginErr');
    if (err) err.textContent = '⚠ 請改用網站網址開啟（不要直接打開下載的檔案），否則無法登入';
    return;
  }
  // Ensure Firebase is initialised (onload timing fix)
  _tryInitFirebase();
  if (!_fbAuth) {
    const err = document.getElementById('loginErr');
    if (typeof firebase === 'undefined') {
      err.textContent = '⚠ 無法載入 Firebase，請確認網路連線後重新整理';
    } else if (typeof firebase.auth !== 'function') {
      err.textContent = '⚠ Firebase Auth 未載入，請重新整理頁面';
    } else {
      err.textContent = '⚠ Firebase 初始化失敗，請重新整理頁面';
    }
    return;
  }
  _fbAuth.onAuthStateChanged(user => {
    const overlay = document.getElementById('loginOverlay');
    if (user) {
      overlay.classList.add('hidden');
      startApp();
      maybeShowProfileSetup();
    } else {
      overlay.classList.remove('hidden');
    }
  });
}

