function toggleLoginMode() {
  setLoginMode(_loginMode === 'login' ? 'register' : 'login');
}

async function doLogin() {
  const email    = document.getElementById('loginEmail').value.trim();
  const password = document.getElementById('loginPassword') ? document.getElementById('loginPassword').value : '';
  const err = document.getElementById('loginErr');
  const btn = document.getElementById('loginBtn');
  err.style.color = '#ff8a80';

  if (_loginMode === 'forgot') {
    if (!email) { err.textContent = '請輸入電子郵件'; return; }
    btn.disabled = true;
    try {
      await _fbAuth.sendPasswordResetEmail(email);
      err.style.color = '#64e07a';
      err.textContent = '重設連結已寄出，請檢查信箱';
    } catch(e) { err.textContent = _authErrMsg(e.code); }
    btn.disabled = false;
    return;
  }

  if (!email || !password) { err.textContent = '請填寫電子郵件和密碼'; return; }
  if (password.length < 6) { err.textContent = '密碼至少需要 6 個字元'; return; }
  if (_loginMode === 'register') {
    const confirm = document.getElementById('loginConfirm').value;
    if (password !== confirm) { err.textContent = '兩次密碼不相符'; return; }
  }

  btn.disabled = true;
  const origText = btn.textContent;
  btn.textContent = '處理中...';
  try {
    await _fbAuth.setPersistence(_rememberMe ? firebase.auth.Auth.Persistence.LOCAL : firebase.auth.Auth.Persistence.SESSION);
  } catch(e) { /* persistence not critical, continue */ }
  const resetBtn = () => { btn.disabled = false; btn.textContent = origText; };
  const timeout = setTimeout(() => {
    resetBtn();
    err.textContent = '⚠ 連線逾時，請確認網路連線後再試一次（若是用下載的檔案開啟，請改用網站網址）';
  }, 10000);
  try {
    if (_loginMode === 'login') {
      await _fbAuth.signInWithEmailAndPassword(email, password);
    } else {
      await _fbAuth.createUserWithEmailAndPassword(email, password);
    }
    clearTimeout(timeout);
  } catch(e) {
    clearTimeout(timeout);
    resetBtn();
    err.textContent = _authErrMsg(e.code);
  }
}

function _authErrMsg(code) {
  const m = {
    'auth/user-not-found':        '找不到此帳號，請先註冊',
    'auth/wrong-password':        '密碼錯誤',
    'auth/invalid-credential':    '帳號或密碼錯誤',
    'auth/invalid-email':         '電子郵件格式錯誤',
    'auth/email-already-in-use':  '此信箱已被使用，請直接登入',
    'auth/weak-password':         '密碼至少需要 6 個字元',
    'auth/too-many-requests':     '嘗試次數過多，請稍後再試',
    'auth/network-request-failed':'網路連線異常',
    'auth/unauthorized-domain':   '⚠ 此網域未授權。請至 Firebase Console → Authentication → Settings → Authorized domains 新增目前網址',
    'auth/operation-not-allowed': '⚠ Email 登入未啟用。請至 Firebase Console → Authentication → Sign-in method 啟用 Email/Password',
  };
  return m[code] || ('操作失敗：' + code);
}

function doLogout() {
  if (_fbAuth) _fbAuth.signOut();
}

async function sendResetEmail() {
  const user = _fbAuth && _fbAuth.currentUser;
  if (!user) { alert('請先登入'); return; }
  try {
    await _fbAuth.sendPasswordResetEmail(user.email);
    alert('重設密碼連結已寄至 ' + user.email);
  } catch(e) { alert(_authErrMsg(e.code)); }
}

function renderHomeWidgets() {
  // 問候語
  const greetEl = document.getElementById('homeGreeting');
  if (greetEl) {
    const h = new Date().getHours();
    const greet = h < 11 ? '早安' : h < 18 ? '午安' : '晚安';
    const name = farmProfile.farmer || '在地小農';
    greetEl.textContent = `${greet}，${name}！`;
  }
  const wloc = document.getElementById('homeWeatherLoc');
  if (wloc) wloc.textContent = farmProfile.location || '台灣在地';

  // 今日農場紀錄摘要（取最新一筆日誌）
  const latest = logs[0];
  const sCrop = document.getElementById('homeSumCrop');
  const sTemp = document.getElementById('homeSumTemp');
  const sHum  = document.getElementById('homeSumHum');
  const sPh   = document.getElementById('homeSumPh');
  const sNote = document.getElementById('homeSumNote');
  if (latest) {
    if (sCrop) sCrop.textContent = latest.type || '農場作物';
    if (sTemp) sTemp.textContent = (latest.temp || latest.temp === 0 ? latest.temp : '--') + '°C';
    if (sHum)  sHum.textContent  = (latest.hum  || latest.hum  === 0 ? latest.hum  : '--') + '%';
    if (sPh)   sPh.textContent   = latest.ph || '--';
    if (sNote) sNote.textContent = latest.note || '（無備註）';
  } else {
    if (sCrop) sCrop.textContent = '尚未紀錄';
    if (sTemp) sTemp.textContent = '--°C';
    if (sHum)  sHum.textContent  = '--%';
    if (sPh)   sPh.textContent   = '--';
    if (sNote) sNote.textContent = '點擊下方按鈕開始今天的第一筆紀錄';
  }

  // 今日任務環狀進度 + 完整清單（6 項）
  const today = _getTodayStr();
  const state = _getDailyTaskState();
  const dailyPhotos = JSON.parse(localStorage.getItem('puli_daily_photos') || '[]');
  const todayPhoto = dailyPhotos.some(p => p.date === today);
  const dateMD = today.slice(5);
  const todayLog = logs.some(l => l.fullDate === today || (l.date && l.date.startsWith(dateMD)));
  const taskDefs = [
    { name:'記錄今日觀測日誌', done: todayLog,  auto: true },
    { name:'澆水',            done: !!state.manual['澆水'], auto: false },
    { name:'上傳今日植物照片', done: todayPhoto, auto: true },
    { name:'施肥',            done: !!state.manual['施肥'], auto: false },
    { name:'除草',            done: !!state.manual['除草'], auto: false },
    { name:'巡視農場',        done: !!state.manual['巡視農場'], auto: false },
  ];
  const done = taskDefs.filter(t => t.done).length;
  const pct = Math.round(done / taskDefs.length * 100);
  const ringOuter = document.getElementById('homeRingOuter');
  const ringText  = document.getElementById('homeRingText');
  const ringSub   = document.getElementById('homeRingSubText');
  if (ringOuter) ringOuter.style.background = `conic-gradient(#37B24D ${pct}%, #E5E7EB 0)`;
  if (ringText) ringText.textContent = done + '/' + taskDefs.length;
  if (ringSub) ringSub.textContent = done + ' 項';

  // 扭蛋剩餘次數
  const tc = document.getElementById('homeTicketCount');
  if (tc) tc.textContent = _tickets;

  // 頭像
  const av = document.getElementById('homeAvatarImg');
  const fb = document.getElementById('homeAvatarFallback');
  if (av) {
    if (farmProfile.photo) { av.src = farmProfile.photo; av.style.display = 'block'; if (fb) fb.style.display = 'none'; }
    else { av.style.display = 'none'; if (fb) fb.style.display = 'block'; }
  }
}



