// ── Consumer Public Profile Functions ──

let _consumerFarmerUid = null;
let _consumerHasLiked = false;

async function loadConsumerPublicProfile() {
  // Step 1: always render from local data immediately (no Firebase needed)
  const nameEl   = document.getElementById('consumerFarmerName');
  const locEl    = document.getElementById('consumerFarmerLoc');
  const titleEl  = document.getElementById('consumerFarmerTitleText');
  const avatarEl = document.getElementById('consumerFarmerAvatar');
  const titlesGrid = document.getElementById('consumerTitlesGrid');
  const dl = document.getElementById('displayLocation');
  const df = document.getElementById('displayFarmer');

  if (nameEl)  nameEl.textContent  = farmProfile.farmer   || '在地小農';
  if (locEl)   locEl.textContent   = '📍 ' + (farmProfile.location || '台灣在地');
  if (titleEl) titleEl.textContent = (typeof _getCurrentTitle === 'function') ? _getCurrentTitle().name : '農場新人';
  if (dl) dl.innerText = farmProfile.location || '台灣在地';
  if (df) df.innerText = farmProfile.farmer   || '在地小農';

  // Avatar placeholder
  if (avatarEl && !avatarEl.src.startsWith('data:image/webp')) {
    avatarEl.src = 'data:image/svg+xml,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><circle cx="32" cy="32" r="32" fill="#2a4a35"/><circle cx="32" cy="24" r="11" fill="rgba(255,255,255,0.5)"/><ellipse cx="32" cy="54" rx="18" ry="12" fill="rgba(255,255,255,0.3)"/></svg>');
  }

  // Titles from local EXP
  if (titlesGrid) {
    titlesGrid.innerHTML = TITLES.map(t => {
      const unlocked = _exp >= t.req;
      return `<span class="consumer-title-badge ${unlocked ? 'unlocked' : ''}"><span aria-hidden="true">${t.icon}</span> ${t.name}</span>`;
    }).join('');
  }

  // Like count placeholder
  const likeEl = document.getElementById('consumerLikeCount');
  if (likeEl) likeEl.textContent = '—';

  // Comment placeholder
  const commentList = document.getElementById('consumerCommentList');
  if (commentList) commentList.innerHTML = '<div style="color:rgba(255,255,255,0.3);font-size:12px;text-align:center;padding:12px 0;">還沒有留言，成為第一個留言的人！</div>';

  // Step 2: get UID (try URL param first, then wait for auth)
  const params = new URLSearchParams(window.location.search);
  let uid = params.get('uid');

  if (!uid) {
    // Wait up to 3s for Firebase Auth to settle
    for (let i = 0; i < 6; i++) {
      if (_fbAuth && _fbAuth.currentUser) { uid = _fbAuth.currentUser.uid; break; }
      await new Promise(r => setTimeout(r, 500));
    }
  }

  if (!uid || !_fbDb) return; // no Firestore data available, local display is enough
  _consumerFarmerUid = uid;

  try {
    // Load richer public profile from Firestore if available
    const profileSnap = await _fbDb.collection('public_profiles').doc(uid).get();
    if (profileSnap.exists) {
      const p = profileSnap.data();
      if (nameEl && p.farmer)   nameEl.textContent  = p.farmer;
      if (locEl  && p.location) locEl.textContent   = '📍 ' + p.location;
      if (titleEl && p.currentTitle) titleEl.textContent = p.currentTitle;
      if (avatarEl && p.photo)  avatarEl.src = p.photo;
      if (titlesGrid && p.exp != null) {
        titlesGrid.innerHTML = TITLES.map(t => {
          const unlocked = p.exp >= t.req;
          return `<span class="consumer-title-badge ${unlocked ? 'unlocked' : ''}"><span aria-hidden="true">${t.icon}</span> ${t.name}</span>`;
        }).join('');
      }
    }

    // Load likes
    const likeSnap = await _fbDb.collection('farm_likes').doc(uid).get();
    if (likeEl) likeEl.textContent = likeSnap.exists ? (likeSnap.data().count || 0) : 0;

    // Check if already liked
    _consumerHasLiked = !!localStorage.getItem('liked_' + uid);
    _updateLikeBtnState();

    // Load comments
    loadConsumerComments(uid);

  } catch(e) { console.warn('loadConsumerPublicProfile:', e); }
}

function _updateLikeBtnState() {
  const btn = document.getElementById('consumerLikeBtn');
  const txt = document.getElementById('consumerLikeBtnText');
  if (!btn) return;
  if (_consumerHasLiked) {
    btn.classList.add('liked');
    if (txt) txt.textContent = '已按讚 ♥';
  } else {
    btn.classList.remove('liked');
    if (txt) txt.textContent = '為這位農夫按讚';
  }
}

async function toggleFarmerLike() {
  if (!_consumerFarmerUid || !_fbDb) return;
  const likedKey = 'liked_' + _consumerFarmerUid;
  const likeRef = _fbDb.collection('farm_likes').doc(_consumerFarmerUid);
  const likeEl  = document.getElementById('consumerLikeCount');

  if (_consumerHasLiked) {
    // Unlike
    _consumerHasLiked = false;
    localStorage.removeItem(likedKey);
    await likeRef.set({ count: firebase.firestore.FieldValue.increment(-1) }, { merge: true });
    if (likeEl) likeEl.textContent = Math.max(0, parseInt(likeEl.textContent) - 1);
  } else {
    // Like
    _consumerHasLiked = true;
    localStorage.setItem(likedKey, '1');
    await likeRef.set({ count: firebase.firestore.FieldValue.increment(1) }, { merge: true });
    if (likeEl) likeEl.textContent = parseInt(likeEl.textContent) + 1;
  }
  _updateLikeBtnState();
}

async function loadConsumerComments(uid) {
  if (!_fbDb) return;
  try {
    const snap = await _fbDb.collection('farm_comments').doc(uid)
      .collection('messages').orderBy('ts', 'desc').limit(30).get();
    const list = document.getElementById('consumerCommentList');
    if (!list) return;
    if (snap.empty) {
      list.innerHTML = '<div style="color:rgba(255,255,255,0.3);font-size:12px;text-align:center;padding:12px 0;">還沒有留言，成為第一個留言的人！</div>';
      return;
    }
    list.innerHTML = snap.docs.map(d => {
      const m = d.data();
      const name = m.name || '匿名';
      const text = m.text || '';
      const ts = m.ts ? new Date(m.ts.seconds * 1000).toLocaleDateString('zh-TW', {month:'numeric',day:'numeric'}) : '';
      return `<div class="comment-item">
        <div><span class="comment-item-name">${name}</span><span class="comment-item-time">${ts}</span></div>
        <div class="comment-item-text">${text}</div>
      </div>`;
    }).join('');
  } catch(e) { console.warn('loadConsumerComments:', e); }
}

async function submitFarmerComment() {
  if (!_consumerFarmerUid || !_fbDb) { alert('無法載入農夫資料，請重新掃描 QR Code'); return; }
  const nameEl = document.getElementById('commentName');
  const textEl = document.getElementById('commentText');
  const name = (nameEl && nameEl.value.trim()) || '匿名';
  const text = textEl && textEl.value.trim();
  if (!text) { alert('請輸入留言內容'); return; }
  try {
    await _fbDb.collection('farm_comments').doc(_consumerFarmerUid)
      .collection('messages').add({ name, text, ts: firebase.firestore.FieldValue.serverTimestamp() });
    if (nameEl) nameEl.value = '';
    if (textEl) textEl.value = '';
    showTicketToast('✓ 留言已送出');
    loadConsumerComments(_consumerFarmerUid);
  } catch(e) { alert('留言失敗：' + e.message); }
}

async function syncPublicProfile() {
  // Called when farmer saves profile — writes a public snapshot to Firestore
  const user = _fbAuth && _fbAuth.currentUser;
  if (!user || !_fbDb) return;
  try {
    const photoSnap = await _fbDb.collection('settings').doc('photo').get();
    const photo = photoSnap.exists ? (photoSnap.data().url || '') : '';
    const curTitle = _getCurrentTitle ? _getCurrentTitle().name : '農場新人';
    await _fbDb.collection('public_profiles').doc(user.uid).set({
      farmer: farmProfile.farmer,
      location: farmProfile.location,
      currentTitle: curTitle,
      exp: _exp,
      photo: photo,
      updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    }, { merge: true });
  } catch(e) { console.warn('syncPublicProfile:', e); }
}

